#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

typedef float v4f __attribute__((vector_size(16)));

#define MR 6
#define NR 8
#define KC 256
#define MC 96
#define NC 2048

static inline v4f ld4(const float *p) { v4f v; memcpy(&v, p, sizeof v); return v; }
static inline void st4(float *p, v4f v) { memcpy(p, &v, sizeof v); }

/* 6x8 micro-kernel: C tile (+)= Apanel(6 x kc) * Bpanel(kc x 8) */
static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int first)
{
    v4f c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v4f c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int p = 0; p < kc; p++) {
        v4f b0 = *(const v4f *)(b);
        v4f b1 = *(const v4f *)(b + 4);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += b0 * a0; c01 += b1 * a0;
        c10 += b0 * a1; c11 += b1 * a1;
        c20 += b0 * a2; c21 += b1 * a2;
        c30 += b0 * a3; c31 += b1 * a3;
        c40 += b0 * a4; c41 += b1 * a4;
        c50 += b0 * a5; c51 += b1 * a5;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        float *r;
#define STROW(i, x0, x1)                                         \
        r = c + (i) * ldc;                                       \
        if (first) { st4(r, x0); st4(r + 4, x1); }               \
        else { st4(r, ld4(r) + x0); st4(r + 4, ld4(r + 4) + x1); }
        STROW(0, c00, c01) STROW(1, c10, c11) STROW(2, c20, c21)
        STROW(3, c30, c31) STROW(4, c40, c41) STROW(5, c50, c51)
#undef STROW
    } else {
        float t[MR][NR];
        st4(&t[0][0], c00); st4(&t[0][4], c01);
        st4(&t[1][0], c10); st4(&t[1][4], c11);
        st4(&t[2][0], c20); st4(&t[2][4], c21);
        st4(&t[3][0], c30); st4(&t[3][4], c31);
        st4(&t[4][0], c40); st4(&t[4][4], c41);
        st4(&t[5][0], c50); st4(&t[5][4], c51);
        for (int i = 0; i < mr; i++)
            for (int j = 0; j < nr; j++) {
                if (first) c[i * ldc + j] = t[i][j];
                else       c[i * ldc + j] += t[i][j];
            }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    int n, r0, r1;
} job_t;

static void *worker(void *arg)
{
    job_t *jb = (job_t *)arg;
    const float *A = jb->A, *B = jb->B;
    float *C = jb->C;
    int n = jb->n, r0 = jb->r0, r1 = jb->r1;
    if (r0 >= r1) return NULL;

    float *Ap = NULL, *Bp = NULL;
    if (posix_memalign((void **)&Ap, 64, sizeof(float) * (MC + MR) * KC)) return NULL;
    if (posix_memalign((void **)&Bp, 64, sizeof(float) * (NC + NR) * KC)) { free(Ap); return NULL; }

    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);

            /* pack B block kc x nc into NR-wide panels, zero-padded */
            for (int jr = 0; jr < nc; jr += NR) {
                float *dst = Bp + (size_t)jr * kc;
                int w = nc - jr < NR ? nc - jr : NR;
                for (int p = 0; p < kc; p++) {
                    const float *src = B + (size_t)(pc + p) * n + jc + jr;
                    int j = 0;
                    for (; j < w; j++) dst[p * NR + j] = src[j];
                    for (; j < NR; j++) dst[p * NR + j] = 0.0f;
                }
            }

            for (int ic = r0; ic < r1; ic += MC) {
                int mc = r1 - ic < MC ? r1 - ic : MC;

                /* pack A block mc x kc into MR-tall panels, zero-padded */
                for (int ir = 0; ir < mc; ir += MR) {
                    float *dst = Ap + (size_t)ir * kc;
                    int h = mc - ir < MR ? mc - ir : MR;
                    for (int i = 0; i < MR; i++) {
                        if (i < h) {
                            const float *src = A + (size_t)(ic + ir + i) * n + pc;
                            for (int p = 0; p < kc; p++) dst[p * MR + i] = src[p];
                        } else {
                            for (int p = 0; p < kc; p++) dst[p * MR + i] = 0.0f;
                        }
                    }
                }

                for (int jr = 0; jr < nc; jr += NR) {
                    int nr = nc - jr < NR ? nc - jr : NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, Bp + (size_t)jr * kc,
                               C + (size_t)(ic + ir) * n + jc + jr, n, mr, nr, first);
                    }
                }
            }
        }
    }

    free(Ap);
    free(Bp);
    return NULL;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    long nt = sysconf(_SC_NPROCESSORS_ONLN);
    if (nt < 1) nt = 1;
    if (nt > 64) nt = 64;
    if ((long)n * n * n < 2000000L) nt = 1;

    int panels = (n + MR - 1) / MR;
    if (nt > panels) nt = panels;

    job_t jobs[64];
    pthread_t th[64];
    int per = (panels + (int)nt - 1) / (int)nt;

    for (int t = 0; t < nt; t++) {
        int r0 = t * per * MR, r1 = (t + 1) * per * MR;
        if (r0 > n) r0 = n;
        if (r1 > n) r1 = n;
        jobs[t].A = A; jobs[t].B = B; jobs[t].C = C;
        jobs[t].n = n; jobs[t].r0 = r0; jobs[t].r1 = r1;
    }

    if (nt == 1) {
        worker(&jobs[0]);
        return;
    }

    int started[64] = {0};
    for (int t = 1; t < nt; t++)
        started[t] = (pthread_create(&th[t], NULL, worker, &jobs[t]) == 0);
    worker(&jobs[0]);
    for (int t = 1; t < nt; t++) {
        if (started[t]) pthread_join(th[t], NULL);
        else worker(&jobs[t]);
    }
}
